}

func main() {
	cfg := &packages.Config{
		Mode: packages.NeedName | packages.NeedFiles | packages.NeedSyntax | packages.NeedTypes | packages.NeedTypesInfo | packages.NeedDeps | packages.NeedImports,
		Dir:  "/bench/repo",
		Tests: true,
	}
	pkgs, err := packages.Load(cfg, "./...")
	if err != nil {
		panic(err)
	}
	counts := map[types.Object]int{}
	callerFiles := map[types.Object]map[string]int{}
	declPos := map[types.Object]string{}

	seen := map[string]bool{}
	packages.Visit(pkgs, nil, func(p *packages.Package) {
		if seen[p.ID] {
			return
		}
		seen[p.ID] = true
		if p.TypesInfo == nil {
			return
		}
		fset := p.Fset
		for _, f := range p.Syntax {
			// record decls
			for _, d := range f.Decls {
				fd, ok := d.(*ast.FuncDecl)
				if !ok {
					continue
				}
				obj := p.TypesInfo.ObjectOf(fd.Name)
				if obj == nil {
					continue
				}
				pos := fset.Position(fd.Pos())
				if strings.Contains(pos.Filename, "/internal/") {
					declPos[obj] = fmt.Sprintf("%s:%d", pos.Filename, pos.Line)
				}
			}
			// record calls
			ast.Inspect(f, func(n ast.Node) bool {
				call, ok := n.(*ast.CallExpr)
				if !ok {
					return true
				}
				var id *ast.Ident
				switch fn := ast.Unparen(call.Fun).(type) {
				case *ast.Ident:
					id = fn
				case *ast.SelectorExpr:
					id = fn.Sel
				case *ast.IndexExpr:
					switch g := ast.Unparen(fn.X).(type) {
					case *ast.Ident:
						id = g
					case *ast.SelectorExpr:
						id = g.Sel
					}
				}
				if id == nil {
					return true
				}
				obj := p.TypesInfo.Uses[id]
				if obj == nil {
					return true
				}
				if fn, ok := obj.(*types.Func); ok {
					if orig := fn.Origin(); orig != nil {
						obj = orig
					}
				}
				counts[obj]++
				pos := fset.Position(id.Pos())
				if callerFiles[obj] == nil {
					callerFiles[obj] = map[string]int{}
				}
				callerFiles[obj][pos.Filename]++
				return true
			})
		}
	})

	type row struct {
		obj types.Object
		n   int
	}
	var rows []row
	for obj, pos := range declPos {
		_ = pos
		rows = append(rows, row{obj, counts[obj]})
	}
	sort.Slice(rows, func(i, j int) bool { return rows[i].n > rows[j].n })
	for i, r := range rows {
		if i >= 30 {
			break
		}
		sig := ""
		if fn, ok := r.obj.(*types.Func); ok {
			if recv := fn.Signature().Recv(); recv != nil {
				sig = "(" + recv.Type().String() + ")."
			}
		}
		nf := len(callerFiles[r.obj])
		fmt.Printf("%4d  %d files  %s%s  @ %s\n", r.n, nf, sig, r.obj.Name(), strings.TrimPrefix(declPos[r.obj], "/bench/repo/"))
	}
	_ = token.NoPos
}
