package main

import (
	"fmt"
	"go/ast"
	"go/types"
	"sort"
	"strings"

	"golang.org/x/tools/go/packages"
)

func main() {
	cfg := &packages.Config{
		Mode:  packages.NeedName | packages.NeedFiles | packages.NeedSyntax | packages.NeedTypes | packages.NeedTypesInfo | packages.NeedDeps | packages.NeedImports,
		Dir:   "/bench/repo",
		Tests: true,
	}
	pkgs, err := packages.Load(cfg, "./...")
	if err != nil {
		panic(err)
	}
	type site struct{ callee, caller string }
	sites := map[site]bool{}
	names := map[string]string{}
	seenPkg := map[string]bool{}

	packages.Visit(pkgs, nil, func(p *packages.Package) {
		if seenPkg[p.ID] || p.TypesInfo == nil {
			return
		}
		seenPkg[p.ID] = true
		fset := p.Fset
		for _, f := range p.Syntax {
			ast.Inspect(f, func(n ast.Node) bool {
				call, ok := n.(*ast.CallExpr)
				if !ok {
					return true
				}
				var id *ast.Ident
				switch fn := ast.Unparen(call.Fun).(type) {
				case *ast.Ident:
					id = fn
				case *ast.SelectorExpr:
					id = fn.Sel
				case *ast.IndexExpr:
					switch g := ast.Unparen(fn.X).(type) {
					case *ast.Ident:
						id = g
					case *ast.SelectorExpr:
						id = g.Sel
					}
				}
				if id == nil {
					return true
				}
				fn, ok := p.TypesInfo.Uses[id].(*types.Func)
				if !ok || fn == nil {
					return true
				}
				if o := fn.Origin(); o != nil {
					fn = o
				}
				dp := fset.Position(fn.Pos())
				if !strings.HasPrefix(dp.Filename, "/bench/repo/internal/") {
					return true
				}
				calleeKey := fmt.Sprintf("%s:%d", strings.TrimPrefix(dp.Filename, "/bench/repo/"), dp.Line)
				label := fn.Name()
				if r := fn.Signature().Recv(); r != nil {
					t := r.Type().String()
					if i := strings.LastIndex(t, "/"); i >= 0 {
						t = t[i+1:]
					}
					label = "(" + t + ")." + fn.Name()
				}
				names[calleeKey] = label
				cp := fset.Position(id.Pos())
				sites[site{calleeKey, fmt.Sprintf("%s:%d:%d", strings.TrimPrefix(cp.Filename, "/bench/repo/"), cp.Line, cp.Column)}] = true
				return true
			})
		}
	})

	prod := map[string]int{}
	test := map[string]int{}
	files := map[string]map[string]bool{}
	for s := range sites {
		if strings.HasSuffix(strings.Split(s.caller, ":")[0], "_test.go") {
			test[s.callee]++
		} else {
			prod[s.callee]++
			if files[s.callee] == nil {
				files[s.callee] = map[string]bool{}
			}
			files[s.callee][strings.Split(s.caller, ":")[0]] = true
		}
	}
	type row struct {
		k          string
		p, t, nf   int
	}
	var rows []row
	for k := range names {
		rows = append(rows, row{k, prod[k], test[k], len(files[k])})
	}
	sort.Slice(rows, func(i, j int) bool {
		if rows[i].p != rows[j].p {
			return rows[i].p > rows[j].p
		}
		return rows[i].t > rows[j].t
	})
	fmt.Printf("%-5s %-5s %-5s %s\n", "prod", "test", "files", "symbol @ decl")
	for i, r := range rows {
		if i >= 25 {
			break
		}
		fmt.Printf("%-5d %-5d %-5d %s @ %s\n", r.p, r.t, r.nf, names[r.k], r.k)
	}
}
